import { atom, read, update } from 'claude-code'
import type { Elements, EngineInterface, RenderElement, Register } from 'claude-code'

import type { GlassAgent, GlassCall, GlassPrompt, GlassServerTool, GlassTurn } from '../types'
import { MAX_PAINTED_LINES, cleanHint, renderHint, clockCells, fmtToolTime, isEditTool, toolText, setCwd, renderAgentLaunch, renderBand, renderBashResult, renderDiff, renderEventRow, renderGroupRow, renderMessageRow, renderNoOutput, renderServerToolRows, renderSkillLoad, renderToolError, renderToolOutput, renderTreeRow, renderUserRow } from './chrome'
import type { ChangedFile, Hunk } from './chrome'
import { G } from './glyphs'
import { parseMarkdown } from './markdown'
import type { Block } from './markdown'
import { PALETTES, paletteNameOf, paletteNamed } from './palette'
import type { Palette, PaletteName } from './palette'
import { themeFileName, themeFor, themeJson, themeSetting } from './theme'
import { writeIntent } from './prose'
import { renderReply } from './render'

// The turns this session, newest last. A user row finds its own turn in
// here: a `read` while a render hook runs subscribes that row, so every
// `update` draws every user row again, and each must still find its data.
const turns = atom({ plugin: 'glass', key: 'turns' } as const, [] as GlassTurn[])
// the prompts the person submitted, newest last: a user row finds its turn
// by text, and the assistant header appears once the turn starts
const prompts = atom({ plugin: 'glass', key: 'prompts' } as const, [] as GlassPrompt[])
// every main-loop call by turn: the dots line, the tree's times, and which
// rows a folded turn hides
const calls = atom({ plugin: 'glass', key: 'calls' } as const, {} as Record<string, GlassCall[]>)
// subagents still running, for the band above the prompt
const agents = atom({ plugin: 'glass', key: 'agents' } as const, [] as GlassAgent[])
const band = atom({ plugin: 'glass', key: 'band' } as const, 'open' as 'open' | 'closed')
// the main-loop turn now running, or null between turns. State, not module
// memory: a hot reload mid-turn rebuilds the module but the host keeps this,
// so an agent finishing inside that turn is not mistaken for one that
// finished after it (review finding, 0.5.1)
const liveTurn = atom({ plugin: 'glass', key: 'liveTurn' } as const, null as string | null)

const HISTORY = 48
// finished replies whose parse is kept for their redraws
const PARSED_MAX = 64
const ANSWER_MAX = 20000

const ESC = String.fromCodePoint(0x1b)
// the engine shows this many output lines before folding the rest behind ctrl+o
// tools whose row never carries a body: a run of them packs without air rows
const COMPACT = new Set(['Read'])

// Live things, ticked once a second: main-loop calls still running (their
// row's clock is a Raster the ticker blits, no redraw) and subagents still
// running (the status line under the prompt). Module state, read by no
// render hook, so a tick redraws nothing in the transcript (2026-10-04).
const liveCalls = new Map<string, { tool: string; t0: number }>()
let ticker: { cancel: () => void } | null = null

async function tick($: EngineInterface, p: Palette): Promise<void> {
  const now = await $.clock.now()
  for (const [id, c] of liveCalls) {
    void $.ui.blit({ requestId: id, key: 'clock', cells: clockCells(now - c.t0, p.meta) }).catch(() => undefined)
  }
  // nothing runs: the ticker stops (no status line: the owner found it noise
  // under the prompt, 2026-10-04)
  if (liveCalls.size === 0) {
    ticker?.cancel()
    ticker = null
  }
}

// A native notification for what the engine stays silent on (0.5.0): the
// engine's own idle notification covers a finished turn, so glass never
// notifies at turn end. On an engine without `$.ui.notify`, or a channel
// that did not send, the text is a toast instead. Never called from a
// render hook, a timer, or on hearing a notification.
// `$.ui.notify` is typed from 2.1.295 on; the call is spelled at the call
// site (the validator asks for `$.noun.event(...)`), typed through a cast of
// `$`, and an engine without it throws into the toast fallback.
type Notifier = { ui: { notify: (text: string, options?: { title?: string }) => Promise<{ isSent: boolean }> } }
async function notifyPerson($: EngineInterface, text: string): Promise<void> {
  try {
    const r = await ($ as unknown as Notifier).ui.notify(text, { title: 'glass' })
    if (r.isSent) return
  } catch {
    // no notify on this engine, or the channel failed: the toast below
  }
  try {
    $.ui.toast(text)
  } catch {
    // a notification is never worth a failed hook
  }
}

// Puts an agent's transcript in the main view, or the main conversation
// back (0.10.0). `$.ui.view` is typed from 2.1.300 on; the call is spelled
// at the call site through a cast of `$`, as notifyPerson's is (the
// validator refuses `$.ui` bound to a value). A `deny` (the agent is gone,
// the view moved, no view on this surface) and an engine without the method
// both end in a toast: a press is never worth a failed hook.
type Viewer = { ui: { view: (v: { agentId?: string }) => Promise<{ deny?: string } | undefined> } }
async function showView($: EngineInterface, v: { agentId?: string }): Promise<void> {
  let text: string | null = null
  try {
    const r = await ($ as unknown as Viewer).ui.view(v)
    if (r?.deny) text = `glass: ${r.deny}`
  } catch {
    text = 'glass: viewing an agent needs Claude Code 2.1.300 or newer'
  }
  if (text === null) return
  try {
    $.ui.toast(text)
  } catch {
    // a toast is never worth a failed hook
  }
}

// Writes a palette's theme to ~/.claude/themes/glass-<palette>.json and
// selects it (0.5.0). The one file glass writes outside its own folder:
// the directory comes from HOME, the name from the closed palette list, the
// content is serialised from hex-checked values. An existing entry under
// that name that is not a regular file (a link, a directory) is left alone.
// The owner's own theme files are never touched. Returns the line to show.
// The engine prefixes a command's answer with the plugin's name, so the
// lines carry none. The engine's `theme` row takes only its built-in names
// from a plugin (seen 2.1.296: `takes one of: auto, dark, light, ...`), so
// the select step is tried and, when refused, the answer names the one
// settings.json line that selects a custom theme.
async function installTheme($: EngineInterface, name: PaletteName): Promise<string> {
  const home = await $.env.get('HOME')
  if (!home || !home.startsWith('/')) return 'HOME is not set, so no theme was written'
  const dir = `${home}/.claude/themes`
  const file = themeFileName(name)
  const shown = `~/.claude/themes/${file}`
  try {
    const hit = (await $.fs.list(dir)).find(x => x.name === file)
    if (hit && (hit.isLink || hit.kind !== 'file')) return `${shown} is not a regular file; nothing written`
  } catch {
    // no themes directory yet: the write creates it
  }
  try {
    await $.fs.write(`${dir}/${file}`, themeJson(themeFor(PALETTES[name], name)))
  } catch {
    return `could not write ${shown}`
  }
  const setting = themeSetting(name)
  const byHand = `wrote ${shown}. A plugin cannot select a custom theme, so pick glass-${name} in /theme.`
  try {
    const r = await $.config.set({ key: 'theme', value: setting })
    if (r.deny) return byHand
  } catch {
    return byHand
  }
  return `theme glass-${name} on (${shown})`
}

// A Bash call's body as glass draws it, or null where the engine's stays.
// Drawn under the ToolUse row from its own `output` (2026-10-04): calls run
// in parallel drew their row with no ToolResult under it, so the body went
// missing; the ToolResult row then draws nothing where this is non-null.
function bashBody(t: Elements['terminal'], p: Palette, output: unknown, isErrored: boolean, cols: number): RenderElement | null {
  if (isErrored) {
    if (typeof output !== 'string' || output.trim() === '') return null
    return renderToolOutput(t, p, output.replace(/\s+$/, '').split('\n'), { columns: cols, maxLines: MAX_PAINTED_LINES })
  }
  const out = output as { stdout?: unknown; stderr?: unknown; interrupted?: unknown; bashEditDiff?: unknown } | undefined
  if (!out || typeof out !== 'object' || typeof out.stdout !== 'string' || out.interrupted === true) return null
  const stderr = typeof out.stderr === 'string' ? out.stderr : ''
  const text = [out.stdout, stderr].filter(s => s.trim() !== '').join('\n').replace(/\s+$/, '')
  const lines = text === '' ? [] : text.split('\n')
  const diff = out.bashEditDiff as { files?: unknown; moreFiles?: unknown } | undefined
  const files = Array.isArray(diff?.files)
    ? (diff!.files as ChangedFile[]).filter(f => f && typeof f.filePath === 'string' && Array.isArray(f.hunks)).map(f => ({ ...f, hunks: f.hunks.filter(h => h && typeof h.oldStart === 'number' && typeof h.newStart === 'number' && Array.isArray(h.lines)) }))
    : []
  if (files.length > 0) {
    const moreFiles = typeof diff?.moreFiles === 'number' ? diff.moreFiles : 0
    return renderBashResult(t, p, lines, files, { maxLines: MAX_PAINTED_LINES, moreFiles, columns: cols })
  }
  if (text === '') return renderNoOutput(t, p)
  if (text.includes(ESC)) return null
  return renderToolOutput(t, p, lines, { columns: cols, maxLines: MAX_PAINTED_LINES })
}

// one main-loop call recorded under its turn, replacing an earlier record
// of the same id
async function setCall($: EngineInterface, turnId: string, call: GlassCall) {
  await update($, calls, r => {
    const record = { ...(r ?? {}) }
    const list = record[turnId] ?? []
    const i = list.findIndex(c => c.id === call.id)
    record[turnId] = i < 0 ? [...list, call] : [...list.slice(0, i), call, ...list.slice(i + 1)]
    return record
  })
}

export const register: Register = (on, options) => {
  const opts = (options ?? {}) as { palette?: unknown; notify?: unknown }
  // the palette follows /config live: every hook reads this binding at
  // draw time, and the config.set hook below swaps it (rows already drawn
  // keep their colors until something redraws them)
  let palette = paletteNamed(opts.palette)
  let paletteName = paletteNameOf(opts.palette)
  // notifications (0.5.0): on unless the option says otherwise; follows /config live
  let notifyOn = opts.notify !== false
  // gutter marks are off for a turn whose prompt asked for writing: the
  // reply is then the thing itself and asks nothing of the reader
  let marks = true
  // the slash commands this session has, for the band's `/tasks` hint
  let commands = new Set<string>()
  // the names and types of subagents this session spawned: their folded
  // `Message from` rows hide, since the finished row says the same
  const spawned = new Set<string>()
  // Tree rows read these module records, never an atom: a read in a render
  // hook subscribes the row, and every write then redraws every row of the
  // turn, which strands duplicate rows above the viewport (2026-10-03).
  const callTurn = new Map<string, string>()
  const callMs = new Map<string, number>()
  // rows of a group the engine unfolded: no ToolResult of their own, so the
  // ToolUse hook draws an Edit's or a Write's card under the row
  const grouped = new Set<string>()
  // each turn's main-loop calls in order, and whether Claude wrote text
  // since the call before: the air rule below reads both
  const turnOrder = new Map<string, { id: string; tool: string; afterText: boolean }[]>()
  let textSinceCall = false
  // /fold and /expand: module state like the records above, so a render
  // hook reads them without subscribing; a hot reload opens everything again
  let foldedTurns = new Set<string>()
  let expandAllNow = false
  // the module records keep the turns the atoms keep: past HISTORY turns
  // the oldest turn's calls go, so a long session does not grow them forever
  const forgetOldTurns = () => {
    for (const [old, list] of turnOrder) {
      if (turnOrder.size <= HISTORY) break
      turnOrder.delete(old)
      foldedTurns.delete(old)
      for (const c of list) {
        callTurn.delete(c.id)
        callMs.delete(c.id)
        grouped.delete(c.id)
      }
    }
  }
  // a finished message redraws on every /fold, resize and palette change:
  // its parse is kept, the newest few by text
  const parsed = new Map<string, Block[]>()
  const parse = (text: string): Block[] => {
    const hit = parsed.get(text)
    if (hit) return hit
    const blocks = parseMarkdown(text)
    parsed.set(text, blocks)
    if (parsed.size > PARSED_MAX) parsed.delete(parsed.keys().next().value!)
    return blocks
  }

  // the live main-loop turn; a hot reload resets it, which only affects the
  // totals of the turn that reloaded
  const live = {
    turnId: '',
    // true from turn.start to the main loop's turn.complete: an agent that
    // finishes outside that window finished after its turn (0.5.0)
    active: false,
    startedAt: 0,
    tools: 0,
    edits: 0,
    failed: 0,
    lastToolId: null as string | null,
    lastFailedTool: null as string | null,
    costStart: null as number | null,
    // tools the API ran inside this turn's requests (0.5.0)
    serverTools: [] as GlassServerTool[],
  }

  on('config.set', { key: 'glass.palette' }, async ($, e, next) => {
    const result = await next(e)
    palette = paletteNamed(e.value)
    paletteName = paletteNameOf(e.value)
    // a glass theme follows the palette (0.5.0); any other theme is left alone
    try {
      const row = (await $.config.list()).find(r => r.key === 'theme')
      if (typeof row?.value === 'string' && row.value.startsWith('custom:glass-')) $.ui.toast('glass: ' + (await installTheme($, paletteName)))
    } catch {
      // the theme stays as it was
    }
    return result
  })

  on('command.run', { command: 'glass-theme' }, async $ => ({ text: await installTheme($, paletteName) }))

  on('config.set', { key: 'glass.notify' }, async ($, e, next) => {
    const result = await next(e)
    notifyOn = e.value !== false
    return result
  })

  on('session.start', async ($, e, next) => {
    // 0.4.2 to 0.4.5 pinned a status line; clear one a reload left behind
    $.ui.status(undefined)
    try {
      setCwd(await $.session.cwd())
    } catch {
      setCwd('')
    }
    try {
      commands = new Set((await $.command.list()).map(c => c.name))
    } catch {
      commands = new Set()
    }
    await $.command.register({ name: 'fold', description: 'glass: fold the tool trees of every finished turn' })
    await $.command.register({ name: 'unfold', description: 'glass: open the tool trees of every turn' })
    await $.command.register({ name: 'expand', description: 'glass: open every folded run of reads and searches' })
    await $.command.register({ name: 'collapse', description: 'glass: fold the runs of reads and searches again' })
    await $.command.register({ name: 'glass-theme', description: 'glass: write a theme for the current palette to ~/.claude/themes and select it' })
    return next(e)
  })
  on('command.run', { command: 'expand' }, async $ => {
    expandAllNow = true
    $.ui.invalidate('ui.render')
    return { text: 'Every folded run is open. /collapse folds them again.' }
  })
  on('command.run', { command: 'collapse' }, async $ => {
    expandAllNow = false
    $.ui.invalidate('ui.render')
    return { text: 'Runs of reads and searches fold again.' }
  })

  // ---- folding on demand -------------------------------------------------
  on('command.run', { command: 'fold' }, async $ => {
    const ids = ((await read($, turns)) ?? []).map(h => h.turnId)
    foldedTurns = new Set(ids.slice(-HISTORY))
    $.ui.invalidate('ui.render')
    return { text: ids.length ? `Folded ${ids.length} turn${ids.length === 1 ? '' : 's'}. /unfold opens them again.` : 'Nothing to fold yet.' }
  })
  on('command.run', { command: 'unfold' }, async $ => {
    foldedTurns = new Set()
    $.ui.invalidate('ui.render')
    return { text: 'Every turn is open.' }
  })

  // ---- reply renderer ----------------------------------------------------
  on('ui.render', { component: 'AssistantMessage' }, ($, e, next) => {
    if (e.surface !== 'terminal') return next(e)
    const text = e.props.text
    if (text.trim() === '') return next(e)
    const t = $.ui.resolve(e)
    // no bullet: the assistant header under the user row carries it
    return renderReply(t, parse(text), palette, {
      first: e.props.isFirstOfReply,
      columns: e.viewport?.columns ?? 80,
      marks,
      // a compaction summary (read-only flag, passed on untouched; typed from
      // 2.1.295 on, so read loosely for older type layouts)
      summary: (e.props as { isSummary?: unknown }).isSummary === true,
    })
  })

  // ---- user row, assistant header, dots line -----------------------------
  on('ui.render', { component: 'UserMessage' }, async ($, e, next) => {
    if (e.surface !== 'terminal') return next(e)
    const t = $.ui.resolve(e)
    const kind = e.props.origin.kind
    // a background task's notification: one tree row, the body under it
    // when the view is expanded (a short one is expanded from the start)
    if (kind === 'task-notification') return renderEventRow(t, palette, e.requestId, e.props.text, e.props.task, e.props.isExpanded)
    // any other row (another agent's message, a scheduled trigger, a
    // bridge): one muted row; ctrl+o keeps the engine's body
    if (kind !== 'composer') {
      if (e.props.isExpanded) return next(e)
      if (spawned.has(e.props.from?.name ?? '')) return t.Box({ display: 'none', children: [] })
      return renderMessageRow(t, palette, e.props.from?.name ?? kind)
    }
    const text = e.props.text
    if (text.trim() === '') return next(e)
    const known = [...((await read($, prompts)) ?? [])].reverse().find(p => p.text === text) ?? null
    const turnId = known?.turnId ?? null
    let turn = null
    if (turnId) {
      const list = ((await read($, calls)) ?? {})[turnId] ?? []
      const done = ((await read($, turns)) ?? []).find(h => h.turnId === turnId) ?? null
      turn = {
        turnId,
        calls: list,
        done,
      }
    }
    const answer = turn?.done?.answer ?? ''
    return renderUserRow(t, palette, {
      text,
      submittedAt: known?.submittedAt ?? null,
      startedAt: known?.startedAt ?? null,
      turn,
      columns: e.viewport?.columns ?? 80,
      // 0.5.0 (gated on the live press retest): the chevron folds this one
      // turn, Copy takes the finished answer
      ...(turnId
        ? {
            folded: foldedTurns.has(turnId),
            onFold: () => {
              if (foldedTurns.has(turnId)) foldedTurns.delete(turnId)
              else foldedTurns.add(turnId)
              $.ui.invalidate('ui.render')
            },
            onCopy: answer ? (press: { surface: 'terminal' | 'desktop' | 'vscode' | 'mobile' }) => void $.ui.copy({ text: answer, surface: press.surface }).catch(() => undefined) : null,
          }
        : {}),
    })
  })

  // ---- tool tree ---------------------------------------------------------
  on('ui.render', { component: 'ToolUse' }, async ($, e, next) => {
    if (e.surface !== 'terminal') return next(e)
    const id = e.props.tool_use_id
    const turnId = callTurn.get(id)
    // a folded turn hides its rows; a row of a turn glass never saw stays
    if (turnId && foldedTurns.has(turnId)) return $.ui.resolve(e).Box({ display: 'none', children: [] })
    const t = $.ui.resolve(e)
    const order = turnId ? turnOrder.get(turnId) : undefined
    const at = order ? order.findIndex(c => c.id === id) : -1
    // Air above every row, except a bare row that continues a run of the
    // same bodiless tool with no prose between (Read, Read, Read). A row
    // after a body, a card, prose or another tool keeps its air (2026-10-04).
    const air = !(order && at > 0 && COMPACT.has(e.props.tool) && order[at - 1]!.tool === e.props.tool && !order[at]!.afterText)
    const started = liveCalls.get(id)
    const clock = e.props.isRunning && started ? clockCells((await $.clock.now()) - started.t0, palette.meta) : undefined
    const row = renderTreeRow(t, palette, e.props, { durationMs: callMs.get(id) ?? null, air, ...(clock ? { clock } : {}) })
    if (grouped.has(id) && (e.props.tool === 'Edit' || e.props.tool === 'Write') && !e.props.isRunning && !e.props.isErrored) {
      const card = editCard(t, palette, e.props.output, e.props.input, e.viewport?.columns ?? 80)
      if (card) return t.Box({ flexDirection: 'column', children: [row, card] })
    }
    if (e.props.tool !== 'Bash' || e.props.isRunning || e.props.output === undefined) return row
    const body = bashBody(t, palette, e.props.output, e.props.isErrored, e.viewport?.columns ?? 80)
    return body ? t.Box({ flexDirection: 'column', children: [row, body] }) : row
  })

  // the engine's folded run of reads and searches: one tree row; /expand
  // opens every group where it is
  on('ui.render', { component: 'ToolGroup' }, async ($, e, next) => {
    if (e.surface !== 'terminal') return next(e)
    if (e.props.isExpanded) {
      remember(grouped, e.props.calls)
      return next(e)
    }
    const first = e.props.calls.find((c: { tool_use_id?: string }) => typeof c.tool_use_id === 'string')
    const turnId = first?.tool_use_id ? callTurn.get(first.tool_use_id) ?? null : null
    if (turnId && foldedTurns.has(turnId)) return $.ui.resolve(e).Box({ display: 'none', children: [] })
    const id = e.requestId
    // open after /expand, or on its own when a call in it failed: a red
    // mark must never hide behind a count
    const failed = e.props.calls.some((c: { isErrored?: boolean; isInterrupted?: boolean }) => c.isErrored || c.isInterrupted)
    if (expandAllNow || failed) {
      remember(grouped, e.props.calls)
      return next({ ...e, props: { ...e.props, isExpanded: true } })
    }
    const t = $.ui.resolve(e)
    return renderGroupRow(t, palette, e.props.calls, {
      isActive: e.props.isActive,
      key: `expand:${id}`,
    })
  })

  // Bash output body, painted. The engine
  // strips escape codes from a rewritten result, so the body is drawn as
  // Text, and only when it is short enough that the engine would show it
  // whole: longer output keeps the engine's collapsed body and ctrl+o.
  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => {
    if (e.surface !== 'terminal') return next(e)
    const turnId = callTurn.get(e.props.tool_use_id)
    if (turnId && foldedTurns.has(turnId)) return $.ui.resolve(e).Box({ display: 'none', children: [] })
    // a failed call's reason on the trunk; a failed Bash's body is the ToolUse row's
    if (e.props.isErrored && e.props.tool !== 'Bash' && typeof e.props.output === 'string') {
      const reason = e.props.output.replace(/<\/?tool_use_error>/g, '')
      if (reason.trim() !== '') return renderToolError($.ui.resolve(e), palette, reason)
    }
    // an Edit's or a Write's diff, drawn as glass draws it (owner's request, 2026-10-03)
    if ((e.props.tool === 'Edit' || e.props.tool === 'Write') && !e.props.isErrored) {
      return editCard($.ui.resolve(e), palette, e.props.output, (e.props as { input?: unknown }).input, e.viewport?.columns ?? 80) ?? next(e)
    }
    // a backgrounded agent: one trunked line in place of the engine's body
    if (e.props.tool === 'Agent' || e.props.tool === 'Task') {
      const status = (e.props.output as { status?: unknown } | undefined)?.status
      if (status === 'async_launched' || status === 'remote_launched') return renderAgentLaunch($.ui.resolve(e), palette, status === 'remote_launched')
      return next(e)
    }
    // a loaded skill: one trunked line in place of the engine's body, whose
    // corner bracket sat off the trunk (2026-10-09)
    if (e.props.tool === 'Skill' && !e.props.isErrored) return renderSkillLoad($.ui.resolve(e), palette, e.props.output)
    if (e.props.tool !== 'Bash') return next(e)
    // a backgrounded command: the same trunked line, not the engine's corner
    // bracket, which sat off the trunk (2026-10-05)
    if (typeof (e.props.output as { backgroundTaskId?: unknown } | undefined)?.backgroundTaskId === 'string' && !e.props.isErrored) return renderAgentLaunch($.ui.resolve(e), palette, false)
    // the ToolUse row draws the body glass owns; this row draws nothing then
    const body = bashBody($.ui.resolve(e), palette, e.props.output, e.props.isErrored, e.viewport?.columns ?? 80)
    return body ? $.ui.resolve(e).Box({ display: 'none', children: [] }) : next(e)
  })

  // ---- the turn's bookkeeping --------------------------------------------
  on('prompt.submit', async ($, e, next) => {
    marks = !writeIntent(e.text)
    const now = await $.clock.now()
    await update($, prompts, ps => [...(ps ?? []), { text: e.text, submittedAt: now, startedAt: null, turnId: null }].slice(-HISTORY))
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    // 2.1.299: turn.start also fires for subagents' and teammates' turns; the
    // live turn is the main loop's (the typings gain agentId with that engine)
    if ((e as { agentId?: string }).agentId) return next(e)
    live.turnId = e.turnId
    live.active = true
    await update($, liveTurn, () => e.turnId)
    live.startedAt = await $.clock.now()
    live.tools = 0
    live.edits = 0
    live.failed = 0
    live.lastToolId = null
    live.lastFailedTool = null
    live.serverTools = []
    live.costStart = null
    try {
      live.costStart = (await $.session.usage()).cost?.usd ?? null
    } catch {
      live.costStart = null
    }
    const { turnId, startedAt } = live
    // the newest prompt with this text gets its turn, which draws the
    // assistant header and the dots line under the user row
    await update($, prompts, ps => {
      const list = [...(ps ?? [])]
      for (let i = list.length - 1; i >= 0; i--) {
        const p = list[i]!
        if (p.text === e.text && p.turnId === null) {
          list[i] = { ...p, startedAt, turnId }
          break
        }
      }
      return list
    })
    await update($, calls, r => {
      const entries = Object.entries(r ?? {}).filter(([k]) => k !== turnId).slice(-(HISTORY - 1))
      return Object.fromEntries([...entries, [turnId, []]])
    })
    // a new turn always shows its tree
    foldedTurns.delete(turnId)
    forgetOldTurns()
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    const main = !e.agentId
    const id = e.tool_use_id ?? ''
    const turnId = live.turnId
    if (main) {
      live.tools += 1
      if (id) live.lastToolId = id
      if (id && turnId) callTurn.set(id, turnId)
      if (id && turnId) turnOrder.set(turnId, [...(turnOrder.get(turnId) ?? []).filter(c => c.id !== id), { id, tool: e.tool, afterText: textSinceCall }])
      textSinceCall = false
      if (id && turnId) await setCall($, turnId, { id, tool: e.tool, status: 'running', ms: null })
      if (id) liveCalls.set(id, { tool: e.tool, t0: await $.clock.now() })
      if (!ticker) ticker = $.clock.every(1000, () => void tick($, palette))
    } else if (e.agentId) {
      const agentId = e.agentId
      const stage = toolText(e.tool)
      const args = e as unknown as Record<string, unknown>
      const file = typeof args.file_path === 'string' ? args.file_path : typeof args.path === 'string' ? args.path : null
      void update($, agents, as => (as ?? []).map(a => (a.agentId === agentId ? { ...a, stage, file: file ?? a.file } : a)))
    }
    if (isEditTool(e.tool)) live.edits += 1
    const t0 = await $.clock.now()
    let r
    try {
      r = await next(e)
    } finally {
      if (main && id) liveCalls.delete(id)
    }
    if (main) {
      const ms = (await $.clock.now()) - t0
      if (r.isError) {
        live.failed += 1
        live.lastFailedTool = e.tool
      }
      if (id) callMs.set(id, ms)
      if (id) liveCalls.delete(id)
      if (id && turnId) await setCall($, turnId, { id, tool: e.tool, status: r.isError ? 'failed' : 'ok', ms })
    }
    return r
  })

  // a subagent's model requests: its tokens and effort for the band. The
  // event streams, so the hook is a generator relaying every chunk; the
  // stop chunk carries the usage.
  on('turn.step', async function* ($, e, next) {
    const stream = next(e)
    let usage: { input_tokens: number; output_tokens: number; cache_read_input_tokens: number; cache_creation_input_tokens: number } | null = null
    let step = await stream.next()
    while (!step.done) {
      const chunk = step.value
      if (chunk.kind === 'stop') usage = chunk.usage
      if (chunk.kind === 'text' && !e.agentId) textSinceCall = true
      yield chunk
      step = await stream.next()
    }
    // tools the API ran inside this request (the advisor): the step's result
    // lists them; the main loop's are drawn after the reply (0.5.0)
    if (!e.agentId) {
      const result = step.value as unknown as { serverToolUses?: ReadonlyArray<{ id: string; name: string; startedAt: number; endedAt?: number }> } | undefined
      for (const s of result?.serverToolUses ?? []) {
        if (typeof s.id !== 'string' || typeof s.name !== 'string' || typeof s.startedAt !== 'number') continue
        if (live.serverTools.some(x => x.id === s.id)) continue
        live.serverTools.push({ id: s.id, name: s.name, startedAt: s.startedAt, ...(typeof s.endedAt === 'number' ? { endedAt: s.endedAt } : {}) })
      }
    }
    if (e.agentId) {
      const agentId = e.agentId
      const effort = e.effort === undefined ? '' : String(e.effort)
      const u = usage
      const used = u ? u.input_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens + u.output_tokens : 0
      void update($, agents, as => (as ?? []).map(a => (a.agentId === agentId ? { ...a, effort: effort || a.effort, tokens: a.tokens + used } : a)))
    }
    return step.value
  })

  on('agent.spawn', async ($, e, next) => {
    const r = await next(e)
    if (e.subagentType) spawned.add(e.subagentType)
    if (typeof (e as { name?: unknown }).name === 'string') spawned.add((e as { name: string }).name)
    if (r.agentId) {
      const agent: GlassAgent = {
        agentId: r.agentId,
        description: e.description,
        kind: e.subagentType,
        model: r.model,
        effort: '',
        stage: 'thinking' + G.ellipsis,
        file: '',
        tokens: 0,
        startedAt: await $.clock.now(),
      }
      await update($, agents, as => [...(as ?? []).filter(a => a.agentId !== agent.agentId), agent])
    }
    return r
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId) {
      const agentId = e.agentId
      const done = ((await read($, agents)) ?? []).find(a => a.agentId === agentId)
      await update($, agents, as => (as ?? []).filter(a => a.agentId !== agentId))
      // an agent that finished after its turn ended: the engine says nothing,
      // so glass does (0.5.0); one that finished inside a turn is on screen.
      // The live turn is read from state, which survives a reload (0.5.1).
      const mainLive = ((await read($, liveTurn)) ?? null) !== null
      if (done && !mainLive && notifyOn) {
        const ms = (await $.clock.now()) - done.startedAt
        const label = done.description.length > 60 ? done.description.slice(0, 59) + G.ellipsis : done.description
        await notifyPerson($, ms >= 100 ? `${label} ${G.middot} ${fmtToolTime(ms)}` : label)
      }
      return next(e)
    }
    const u = e.usage
    let costUsd: number | null = null
    if (live.costStart !== null) {
      try {
        const now = (await $.session.usage()).cost?.usd
        if (typeof now === 'number') costUsd = Math.max(0, now - live.costStart)
      } catch {
        costUsd = null
      }
    }
    const finishedAt = await $.clock.now()
    const turn: GlassTurn = {
      turnId: e.turnId,
      durationMs: e.durationMs,
      tools: live.tools,
      edits: live.edits,
      failed: live.failed,
      inTokens: u ? u.input_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens : 0,
      cacheTokens: u ? u.cache_read_input_tokens : 0,
      outTokens: u ? u.output_tokens : 0,
      costUsd,
      lastToolId: live.lastToolId,
      answer: e.answer.slice(0, ANSWER_MAX),
      startedAt: live.startedAt || finishedAt - e.durationMs,
      finishedAt,
      ...(live.serverTools.length ? { serverTools: [...live.serverTools] } : {}),
    }
    await update($, turns, h => [...(h ?? []), turn].slice(-HISTORY))
    live.active = false
    await update($, liveTurn, () => null)
    // a turn that ended with failed calls: the engine's idle notification
    // does not say so (0.5.0)
    if (live.failed > 0 && notifyOn) {
      await notifyPerson($, `${live.failed} ${live.failed === 1 ? 'call' : 'calls'} failed${live.lastFailedTool ? ` ${G.middot} ${toolText(live.lastFailedTool)}` : ''}`)
    }
    // a finished turn stays open: the tree is the evidence of what the
    // prompt did (owner's call, 2026-10-03; /fold tucks old turns away)
    return next(e)
  })

  // ---- footer ------------------------------------------------------------
  // The engine's `Baked for 12s` line is dropped by request: the dots line
  // under the user row carries the counts, and the turn's cost and
  // tokens stay in state for anything that wants them later.
  on('ui.render', { component: 'TurnDuration' }, async ($, e, next) => {
    if (e.surface !== 'terminal') return next(e)
    const t = $.ui.resolve(e)
    // the one per-turn row after the reply: it carries the tools the API ran
    // itself, when the turn had any (0.5.0). It finds its turn by duration,
    // as the footer did; this read subscribes one row per turn.
    const list = (await read($, turns)) ?? []
    let mine: GlassTurn | null = null
    for (let i = list.length - 1; i >= 0; i--) {
      if (list[i]!.durationMs === e.props.durationMs) {
        mine = list[i]!
        break
      }
    }
    const tools = mine?.serverTools ?? []
    if (tools.length === 0) return t.Box({ display: 'none', children: [] })
    return renderServerToolRows(t, palette, tools)
  })

  // ---- the hint line under the prompt: key reminders dropped ---------------
  on('ui.render', { component: 'PromptHint' }, ($, e, next) => {
    if (e.surface !== 'terminal') return next(e)
    const h = cleanHint(e.props.hint)
    return h ? renderHint($.ui.resolve(e), palette, h) : next(e)
  })

  // ---- spinner: the action count while tools run -------------------------
  on('ui.render', { component: 'Spinner' }, ($, e, next) => {
    if (e.surface !== 'terminal' || e.props.mode !== 'tool-use' || live.tools === 0) return next(e)
    const n = live.tools
    return next({ ...e, props: { ...e.props, suffix: `${G.ellipsis} ${G.middot} ${n} ${n === 1 ? 'action' : 'actions'}` } })
  })

  // ---- background band ---------------------------------------------------
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.surface !== 'terminal' || e.props.hasSurvey) return next(e)
    // The band is one site for every plugin: what the plugins beneath draw
    // stays, under the agents' frame, and alone when no agent runs.
    const below = await next(e)
    const list = (await read($, agents)) ?? []
    if (list.length === 0) return below
    const t = $.ui.resolve(e)
    const state = (await read($, band)) ?? 'open'
    // 0.10.0: `view` puts the agent's transcript in the main view and `back`
    // returns, through `$.ui.view` (engine 2.1.300) in showView. The site
    // says which agent is in view.
    const frame = renderBand(t, palette, {
      agents: list,
      now: await $.clock.now(),
      columns: e.props.bodyColumns,
      open: state === 'open',
      onToggle: () => void update($, band, s => (s === 'closed' ? 'open' : 'closed')),
      tasksCommand: commands.has('tasks') ? 'tasks' : commands.has('bashes') ? 'bashes' : null,
      viewing: e.props.view?.agentId ?? null,
      onView: (agentId: string) => void showView($, { agentId }),
      onBack: () => void showView($, {}),
    })
    return t.Box({ flexDirection: 'column', children: [frame, below] })
  })
}

/** Keeps the tool_use_ids of an unfolded group's calls. */
function remember(ids: Set<string>, calls: ReadonlyArray<{ tool_use_id?: string }>): void {
  for (const c of calls) if (typeof c.tool_use_id === 'string') ids.add(c.tool_use_id)
}

/**
 * An Edit's or a Write's result as glass's diff card, null when there is
 * nothing to draw. A Write that created the file has no patch: its whole
 * content draws as added lines under `Created`.
 */
function editCard(t: Elements['terminal'], palette: Palette, output: unknown, input: unknown, columns: number): RenderElement | null {
  const out = output as { structuredPatch?: unknown; filePath?: unknown; type?: unknown; content?: unknown } | undefined
  const patch = out?.structuredPatch
  const patched = Array.isArray(patch) ? (patch as Hunk[]).filter(h => h && typeof h.oldStart === 'number' && typeof h.newStart === 'number' && Array.isArray(h.lines)) : []
  const created = patched.length === 0 && out?.type === 'create' && typeof out.content === 'string'
  const hunks = created ? [{ oldStart: 0, newStart: 1, lines: (out.content as string).replace(/\n$/, '').split('\n').map(l => `+${l}`) }] : patched
  if (hunks.length === 0) return null
  const args = input as { file_path?: unknown } | undefined
  const path = typeof out?.filePath === 'string' ? out.filePath : typeof args?.file_path === 'string' ? args.file_path : ''
  return renderDiff(t, palette, hunks, { path, columns, ...(created ? { verb: 'Created' } : {}) })
}

files.hooks/chrome.ts:
// Turn chrome, following SPEC.md "Turn chrome": the user row with its
// assistant header and dots line, the tool tree, the folded group, event
// rows and the background band. One glyph
// family (glyphs.ts), one ruler (width.ts), one hierarchy rule: bright for
// the live thing, `meta` for the done thing, `faint` for scaffolding,
// saturated color on marks only.
import type { Elements, RenderElement, RenderNode, UiPressArgument } from 'claude-code'

import type { GlassAgent, GlassCall, GlassServerTool, GlassTurn } from '../types'
import { G } from './glyphs'
import { codeColor, highlightLine, langOf } from './highlight'
import type { State } from './highlight'
import { paintLine } from './output'
import type { Palette } from './palette'
import { measure } from './render'
import { shellSpans } from './shell'
import { THEME } from './theme'
import { cellWidth, clipPath } from './width'

type Table = Elements['terminal']
type Press = (e: UiPressArgument) => void

// the API bounds a Text string at this many characters
const MAX_TEXT = 10000

const EDIT_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit', 'MultiEdit'])
export function isEditTool(name: string): boolean {
  return EDIT_TOOLS.has(name)
}

// `3:31 PM` in the machine's locale
const clock = new Intl.DateTimeFormat(undefined, { hour: 'numeric', minute: '2-digit' })
export function clockTime(ms: number): string {
  return clock.format(ms)
}

export function fmtDuration(ms: number): string {
  const s = Math.round(ms / 1000)
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  if (m < 60) return `${m}m ${String(s % 60).padStart(2, '0')}s`
  // an hour on: `2h 05m`, so the clock's seven cells still hold it whole
  return `${Math.floor(m / 60)}h ${String(m % 60).padStart(2, '0')}m`
}

// a tool's wall time: tenths under ten seconds, whole seconds after
export function fmtToolTime(ms: number): string {
  if (ms < 10_000) return `${(ms / 1000).toFixed(1)}s`
  return fmtDuration(ms)
}

export function fmtTokens(n: number): string {
  if (n < 1000) return String(n)
  if (n < 10_000) return `${(n / 1000).toFixed(1)}k`
  if (n < 1e6) return `${Math.round(n / 1000)}k`
  return `${(n / 1e6).toFixed(1)}M`
}

// Empryo's rule: three decimals under a cent, two from there
export function fmtCost(usd: number): string {
  if (usd < 0.01) return `$${usd.toFixed(3)}`
  return `$${usd.toFixed(2)}`
}

// a Text string the API accepts: tab and newline are the only controls
export function safeText(s: string, max = MAX_TEXT): string {
  const clean = s.replace(/\r\n?/g, '\n').replace(/[\x00-\x08\x0b-\x1f\x7f]/g, '')
  return clean.length > max ? clean.slice(0, max - 1) + G.ellipsis : clean
}

// cut to `n` cells with an ellipsis
export function clip(s: string, n: number): string {
  if (cellWidth(s) <= n) return s
  // no room: nothing, not a lone ellipsis a cell past the edge
  if (n <= 0) return ''
  let out = ''
  for (const ch of s) {
    if (cellWidth(out + ch) > n - 1) break
    out += ch
  }
  return out + G.ellipsis
}

// pad or cut to exactly `n` cells
function fit(s: string, n: number): string {
  const c = clip(s, n)
  return c + ' '.repeat(Math.max(0, n - cellWidth(c)))
}

// a path padded or cut to exactly `n` cells, cut in the middle so the file
// name stays: `hooks/...render.ts`, not `hooks/rend...`
function fitPath(s: string, n: number): string {
  const c = clipPath(s, n)
  return c + ' '.repeat(Math.max(0, n - cellWidth(c)))
}

// a row of air above a tree row, with the trunk drawn through it so the
// tree stays one line (the owner wants a blank between runs, 2026-10-03)
// Tree rows sit 2 cells in from each edge (owner's request, 2026-10-03:
// the right column was flush with the terminal's edge), the same 2 the
// prose measure leaves on the right.
const TREE_INSET = 2
function spaced(t: Table, p: Palette, row: RenderElement, air = true): RenderElement {
  return t.Box({ flexDirection: 'column', marginLeft: TREE_INSET, marginRight: TREE_INSET, children: air ? [t.Text({ color: p.faint, children: [G.pipe] }), row] : [row] })
}

// the session's directory: paths under it draw relative (`SPEC.md`, not
// the whole home path); set at session.start, empty draws paths whole
let cwd = ''
export function setCwd(dir: string): void {
  cwd = dir.replace(/\/+$/, '')
}
export function rel(path: string): string {
  return cwd && path.startsWith(cwd + '/') ? path.slice(cwd.length + 1) : path
}

const plural = (n: number, one: string) => `${n} ${n === 1 ? one : one + 's'}`
const sep = ` ${G.middot} `

// ---- user row ------------------------------------------------------------

export type TurnView = {
  turnId: string
  calls: GlassCall[]
  /** the finished turn, once it is */
  done: GlassTurn | null
}

export type UserRow = {
  text: string
  submittedAt: number | null
  /** when the turn for this prompt began; the assistant header follows once known */
  startedAt: number | null
  turn: TurnView | null
  columns: number
  /** 0.5.0, gated on the live press retest: the turn's tree is folded */
  folded?: boolean
  /** a press folds or unfolds this turn's tree; none, no chevron */
  onFold?: Press | null
  /** a press copies the turn's answer; none, no Copy */
  onCopy?: Press | null
}

// the dots: one per call in call order, grouped by consecutive tool with a
// space between groups; `ok` green, `err` red, hollow while running. Past
// DOTS_MAX calls the first DOTS_SHOWN draw and `+N` in `faint` stands for
// the rest, so the summary after them is never pushed off the row (45
// calls filled 80 columns with dots, 2026-10-06); the summary keeps every
// count, failures included.
const DOTS_MAX = 16
const DOTS_SHOWN = 12
function dots(t: Table, p: Palette, calls: GlassCall[]): RenderNode[] {
  const out: RenderNode[] = []
  let prev: string | null = null
  const shown = calls.length > DOTS_MAX ? calls.slice(0, DOTS_SHOWN) : calls
  for (const c of shown) {
    if (prev !== null && c.tool !== prev) out.push(t.Text({ children: [' '] }))
    prev = c.tool
    const mark = c.status === 'running' ? G.hollow : c.status === 'failed' ? G.cross : G.disc
    const color = c.status === 'failed' ? p.err : c.status === 'ok' ? p.ok : p.meta
    // the dot and its tree row light together under the pointer
    out.push(t.Text({ color, hover: { scope: callScope(c.id), backgroundColor: p.rowHover }, children: [mark] }))
  }
  if (shown.length < calls.length) out.push(t.Text({ color: p.faint, children: [` +${calls.length - shown.length}`] }))
  return out
}

// `Bash x3 . Read x2`: the tools in first-seen order with their counts
function toolCounts(calls: GlassCall[]): string {
  const counts = new Map<string, number>()
  for (const c of calls) counts.set(c.tool, (counts.get(c.tool) ?? 0) + 1)
  return [...counts].map(([tool, n]) => (n > 1 ? `${toolText(tool)} ${G.times}${n}` : toolText(tool))).join(sep)
}

// ---- tool names ----------------------------------------------------------

// MCP tools arrive as `mcp__<server>__<tool>`: the label drops `mcp__` and
// splits the rest, the server drawn once in `faint` before the name. Servers
// lose the prefixes Claude Code adds (`plugin_<plugin>_`, `claude_ai_`) and
// a trailing `_MCP`, and read in kebab case; a name's underscore runs fold
// to one, or to spaces under NAME_SPACES (owner's request, 2026-10-07:
// `mcp__figma__get_design_context` read as rules, not a name). The server
// was `meta` first, which read lighter than the faint subject on water.
const NAME_SPACES = false
export type ToolLabel = { server: string | null; name: string }
export function toolLabel(tool: string): ToolLabel {
  const m = /^mcp__(.+?)__(.+)$/.exec(tool)
  if (!m) return { server: null, name: tool.replace(/_+/g, '_') }
  const server = m[1]!.replace(/^plugin_[^_]+_(?=.)/, '').replace(/^claude_ai_(?=.)/, '').replace(/(?<=.)_mcp$/i, '')
  const name = NAME_SPACES ? m[2]!.replace(/_+/g, ' ').trim() : m[2]!.replace(/_+/g, '_')
  return { server: server.toLowerCase().replace(/_+/g, '-'), name: name || m[2]! }
}
export function toolText(tool: string): string {
  const l = toolLabel(tool)
  return l.server ? `${l.server} ${l.name}` : l.name
}
function toolNodes(t: Table, p: Palette, tool: string, bold: boolean): RenderNode[] {
  const l = toolLabel(tool)
  const name = t.Text({ color: p.tool, bold, children: [l.name] })
  return l.server ? [t.Text({ color: p.faint, children: [l.server + ' '] }), name] : [name]
}

// `<diamond> You . 01:11 PM`, the prompt under it at the measure, then after
// one blank row the assistant header `<fisheye> Claude . 01:14 PM` and the
// dots line: the one place a header can sit above both the tool rows and
// the reply, since the engine fixes the row order. Folded, the dots line
// reads the tool counts while the turn runs and the totals once it is
// done.
export function renderUserRow(t: Table, p: Palette, r: UserRow): RenderElement {
  const m = measure(r.columns)
  const rows: RenderElement[] = [
    // a turn separator: one blank row, a faint rule the measure wide, one
    // more blank row, so a new prompt stands apart from the reply above
    // (owner's request, 2026-10-03)
    // the turn boundary is one titled rule: `<diamond> You . 3:20 PM ---`
    // to the measure, a blank row above it (proposal 7, 2026-10-04: it
    // replaces a bare rule with a blank row each side, two rows saved)
    t.Box({
      marginTop: 1,
      children: [
        t.Text({
          wrap: 'truncate-end',
          children: [
            // name and glyph in one color: a neutral bold name was tried
            // and the owner wanted the color back (2026-10-11)
            t.Text({ color: p.accentUser, bold: true, children: [G.diamond + ' You'] }),
            ...(r.submittedAt === null ? [] : [t.Text({ color: p.meta, children: [sep + clockTime(r.submittedAt)] })]),
            t.Text({ color: p.faint, children: [' ' + G.rule.repeat(Math.max(1, m - cellWidth(G.diamond + ' You' + (r.submittedAt === null ? '' : sep + clockTime(r.submittedAt))) - 1))] }),
          ],
        }),
      ],
    }),
    t.Box({ marginLeft: 2, width: m, children: [t.Text({ wrap: 'wrap', children: [safeText(r.text)] })] }),
  ]
  if (r.startedAt !== null) {
    rows.push(
      t.Box({
        marginTop: 1,
        children: [
          t.Text({
            children: [
              t.Text({ color: p.accent, bold: true, children: [G.fisheye + ' Claude'] }),
              t.Text({ color: p.meta, children: [sep + clockTime(r.startedAt)] }),
            ],
          }),
        ],
      }),
    )
  }
  const v = r.turn
  if (v && v.calls.length > 0) {
    const summary: RenderNode[] = []
    if (v.done) {
      summary.push(plural(v.done.tools, 'action'))
      if (v.done.edits > 0) summary.push(sep + plural(v.done.edits, 'edit'))
      if (v.done.failed > 0) summary.push(sep, t.Text({ color: p.err, children: [`${v.done.failed} failed`] }))
    } else {
      summary.push(toolCounts(v.calls))
      const failed = v.calls.filter(c => c.status === 'failed').length
      if (failed > 0) summary.push(sep, t.Text({ color: p.err, children: [`${failed} failed`] }))
    }
    // dots as sibling Texts, so each can light its row (a Text nested in a
    // Text follows its hover group but cannot heat it)
    const left = t.Box({
      flexDirection: 'row',
      flexShrink: 1,
      children: [...dots(t, p, v.calls), t.Text({ children: ['  '] }), t.Box({ flexShrink: 1, children: [t.Text({ wrap: 'truncate-end', color: v.done ? p.meta : p.bold, children: summary })] })],
    })
    // 0.5.0: the chevron and Copy return as plain Buttons at the right end,
    // gated on the live press retest (the 0.2 and 0.3 Buttons never
    // received a press; 2.1.288 fixed button routing). /fold and /unfold
    // stay the keyboard route. Label only: no children, so the tree
    // validates on engines before 2.1.295.
    const controls: RenderNode[] = []
    if (r.onFold) controls.push(t.Button({ key: `fold:${v.turnId}`, label: r.folded ? G.right : G.down, plain: true, dimColor: true, hover: { backgroundColor: p.rowHover }, onPress: r.onFold }))
    if (r.onCopy && v.done) controls.push(...(controls.length ? ['  '] : []), t.Button({ key: `copy:${v.turnId}`, label: G.copy + ' Copy', plain: true, dimColor: true, hover: { backgroundColor: p.rowHover }, onPress: r.onCopy }))
    rows.push(
      t.Box({
        key: `dots:${v.turnId}`,
        flexDirection: 'row',
        marginLeft: 2,
        // the same right inset as the tree rows, so the buttons end where
        // the durations end
        marginRight: TREE_INSET,
        justifyContent: 'space-between',
        hover: { backgroundColor: p.rowHover },
        children: [
          t.Box({ flexDirection: 'row', flexShrink: 1, children: [left] }),
          ...(controls.length ? [t.Box({ flexDirection: 'row', flexShrink: 0, marginLeft: 2, children: controls })] : []),
        ],
      }),
    )
  }
  return t.Box({ flexDirection: 'column', children: rows })
}

// ---- tool tree -----------------------------------------------------------

export type TreeRow = {
  tool_use_id: string
  tool: string
  input: unknown
  isRunning: boolean
  isErrored: boolean
  isInterrupted: boolean
  output?: unknown
}

// no `last`: knowing a turn's last call needs a subscription to the turn,
// so every row draws the tee and the trunk runs on (0.3.10)
export type TreeOptions = {
  /** wall time once known */
  durationMs: number | null
  /** a trunk row above; false inside a run of the same tool (2026-10-04) */
  air?: boolean
  /** while running: the clock's first cells (clockCells); a ticker blits the rest */
  clock?: string
}

function str(args: Record<string, unknown>, k: string): string | null {
  return typeof args[k] === 'string' ? (args[k] as string) : null
}

// the subject of a row: a Bash command tokenized, live or done (the owner
// liked the colors on the done row, 2026-10-05); other subjects step down
// to faint once done
function subjectNodes(t: Table, p: Palette, tool: string, input: unknown, live: boolean): RenderNode[] {
  const args = (input ?? {}) as Record<string, unknown>
  const out: RenderNode[] = []
  const command = tool === 'Bash' ? str(args, 'command') : null
  if (command) {
    const text = safeText(command.replace(/\s*\n\s*/g, ' '), 400)
    const spans = shellSpans(text, true) ?? [{ text, kind: 'plain' as const }]
    for (const s of spans) out.push(s.kind === 'plain' ? s.text : t.Text({ color: p[s.kind], children: [s.text] }))
    return out
  }
  const path = str(args, 'file_path') ?? str(args, 'path') ?? str(args, 'notebook_path')
  const url = str(args, 'url')
  const other = str(args, 'pattern') ?? str(args, 'query') ?? str(args, 'description') ?? str(args, 'skill') ?? str(args, 'prompt') ?? str(args, 'command')
  // a done row steps everything after the name down to faint, paths included
  if (other && !path) out.push(t.Text({ ...(live ? {} : { color: p.faint }), children: [safeText(other.replace(/\s*\n\s*/g, ' '), 200)] }))
  if (path) out.push(t.Text({ color: live ? p.path : p.faint, children: [safeText(rel(path), 400)] }))
  if (url) out.push(t.Text({ color: live ? p.url : p.faint, underline: live, children: [safeText(url, 400)] }))
  if (other && path) out.push(t.Text({ color: live ? p.meta : p.faint, children: [sep + safeText(other.replace(/\s*\n\s*/g, ' '), 200)] }))
  return out
}

// lines a Bash result holds, for the `. N lines` tail of a done row
function outputLines(output: unknown): number | null {
  if (!output || typeof output !== 'object') return null
  const o = output as { stdout?: unknown; stderr?: unknown }
  const text = [o.stdout, o.stderr].filter((s): s is string => typeof s === 'string' && s.trim() !== '').join('\n').replace(/\s+$/, '')
  return text === '' ? 0 : text.split('\n').length
}

// The connector and mark that open a tree row, in a box that never shrinks.
// A Text in a row shrinks with its siblings: when the subject overflows, the
// row squeezed the two-cell `o ` mark to one cell and the gap after it went
// (`oBash  cat > ...`, seen 2026-10-05). Only the subject truncates now.
function rowHead(t: Table, ...cells: RenderElement[]): RenderElement {
  return t.Box({ flexDirection: 'row', flexShrink: 0, children: cells })
}

// `|- v Bash  git log --oneline . 3 lines                        0.8s`
// Connector `faint`, mark in its status color, the name in `tool` (bold
// while live), the subject truncating (ctrl+o has the whole call), the
// time at the right. The row lights under the pointer.
export function renderTreeRow(t: Table, p: Palette, row: TreeRow, o: TreeOptions): RenderElement {
  const live = row.isRunning
  const failed = row.isErrored || row.isInterrupted
  const mark = live ? G.hollow : failed ? G.cross : G.tick
  // the tick in `ok`: a meta tick was tried and the owner wanted the green
  // back (2026-10-11)
  const markColor = live ? p.meta : failed ? p.err : p.ok
  const subject = subjectNodes(t, p, row.tool, row.input, live)
  const tail: RenderNode[] = []
  if (!live && row.tool === 'Bash') {
    // the count only once the body folds: a three-line body is its own count
    const n = outputLines(row.output)
    if (n !== null && n > MAX_PAINTED_LINES) tail.push(t.Text({ color: p.faint, children: [sep + plural(n, 'line')] }))
  }
  // under a tenth of a second the time says nothing (`0.0s`): none
  const right = o.durationMs === null || o.durationMs < 100 ? '' : fmtToolTime(o.durationMs)
  return spaced(t, p, t.Box({
    key: `row:${row.tool_use_id}`,
    flexDirection: 'row',
    hover: { scope: callScope(row.tool_use_id), backgroundColor: p.rowHover },
    children: [
      rowHead(t, t.Text({ color: p.faint, children: [G.tee + G.rule + ' '] }), t.Text({ color: markColor, children: [mark + ' '] })),
      t.Box({
        flexGrow: 1,
        flexShrink: 1,
        children: [
          t.Text({
            wrap: 'truncate-end',
            children: [...toolNodes(t, p, row.tool, live), ...(subject.length ? ['  ', ...subject] : []), ...tail],
          }),
        ],
      }),
      ...(live && o.clock && 'Raster' in t
        ? [t.Box({ flexShrink: 0, marginLeft: 2, children: [t.Raster({ key: 'clock', columns: CLOCK_CELLS, rows: 1, cells: o.clock })] })]
        : right
          ? [t.Box({ flexShrink: 0, marginLeft: 2, children: [t.Text({ color: live ? p.meta : p.faint, children: [right] })] })]
          : []),
    ],
  }), o.air ?? true)
}

// A tool the API ran inside the request (the advisor): no tool.call, no
// engine row, so the turn's record draws these after the reply (0.5.0).
// `|- v advisor  ran by the API                                   4.2s`
// Connector faint, the mark in meta (the engine ran nothing, so not ok's
// done), the name in `tool`, the note faint, the duration faint as on every
// finished row; none without an end time. Each row keeps its air row above.
export function renderServerToolRows(t: Table, p: Palette, tools: ReadonlyArray<GlassServerTool>): RenderElement {
  const rows = tools.map(s => {
    const right = s.endedAt === undefined || s.endedAt - s.startedAt < 100 ? '' : fmtToolTime(s.endedAt - s.startedAt)
    return spaced(t, p, t.Box({
      key: `server:${s.id}`,
      flexDirection: 'row',
      hover: { backgroundColor: p.rowHover },
      children: [
        rowHead(t, t.Text({ color: p.faint, children: [G.tee + G.rule + ' '] }), t.Text({ color: p.meta, children: [G.tick + ' '] })),
        t.Box({
          flexGrow: 1,
          flexShrink: 1,
          children: [t.Text({ wrap: 'truncate-end', children: [...toolNodes(t, p, safeText(s.name, 60), false), '  ', t.Text({ color: p.faint, children: ['ran by the API'] })] })],
        }),
        ...(right ? [t.Box({ flexShrink: 0, marginLeft: 2, children: [t.Text({ color: p.faint, children: [right] })] })] : []),
      ],
    }))
  })
  return t.Box({ flexDirection: 'column', children: rows })
}

// cells a body row leaves for the trunk column before its content
const TRUNK = 3
// painted output lines under a Bash row before the rest folds to a count
export const MAX_PAINTED_LINES = 3

// A body row under a tree row: the trunk down its left, `h` rows tall,
// the content indented under the row's mark.
function trunked(t: Table, p: Palette, h: number, content: RenderNode[]): RenderElement {
  return t.Box({
    flexDirection: 'row',
    marginLeft: TREE_INSET,
    marginRight: TREE_INSET,
    children: [
      t.Box({ width: TRUNK, flexShrink: 0, children: [t.Text({ color: p.faint, children: [Array(Math.max(1, h)).fill(G.pipe).join('\n')] })] }),
      t.Box({ flexGrow: 1, flexShrink: 1, flexDirection: 'column', children: content }),
    ],
  })
}

// characters of one output line kept: more than any terminal row shows
const OUTPUT_LINE_MAX = 1000

// a line as a terminal leaves it: a carriage return (a progress bar's
// `50%\r100%`) starts the line over, so only the last pass shows
function overstruck(line: string): string {
  const s = line.replace(/\r+$/, '')
  return s.slice(s.lastIndexOf('\r') + 1)
}

export type OutputOptions = {
  columns: number
  /** lines past this fold to a `faint` count */
  maxLines: number
}

// The engine's Bash result body, redrawn so the output can be painted (the
// engine strips escape codes from a rewritten result, so colors have to be
// Text) and so the trunk runs through it: one trunked row per line, the
// rest folded to `+N lines`. (The dentistry-symbol connector and the engine's own
// collapsed body for long output were the first design; both broke the
// tree's line, owner's request 2026-10-03.)
export function renderToolOutput(t: Table, p: Palette, lines: string[], o: OutputOptions = { columns: 80, maxLines: lines.length }): RenderElement {
  const shown = lines.slice(0, o.maxLines)
  // one row per output line, clipped: a long line no longer doubles the
  // body's height, and ctrl+o has the whole output (2026-10-04)
  // each line made a string the API takes: no control characters (a `\b`
  // or a bell refused the whole tree) and cut well past any terminal's
  // width, since the row clips anyway (a minified JSON line ran 16000)
  const rows = shown.map(line =>
    trunked(t, p, 1, [
      t.Text({
        wrap: 'truncate-end',
        children: paintLine(safeText(overstruck(line), OUTPUT_LINE_MAX)).map(s => (s.color ? t.Text({ color: p[s.color], children: [s.text] }) : t.Text({ color: p.meta, children: [s.text] }))),
      }),
    ]),
  )
  const rest = lines.length - shown.length
  if (rest > 0) rows.push(trunked(t, p, 1, [t.Text({ color: p.faint, children: [G.ellipsis + ` +${plural(rest, 'line')}`] })]))
  return t.Box({ flexDirection: 'column', children: rows })
}

// ---- an Edit's diff ------------------------------------------------------

export type Hunk = { oldStart: number; newStart: number; lines: string[] }

export type DiffOptions = {
  /** the file's path, for the highlighter's language */
  path: string
  /** the terminal's width */
  columns: number
  /** `Created` or `Deleted` before the path in the title; absent for an update */
  verb?: string
}

// rows a diff body draws before folding the rest into a count
const MAX_DIFF_ROWS = 200
const DIFF_MIN = 60

// An Edit's `structuredPatch` as glass draws it, in place of the engine's
// own diff panel (owner's request, 2026-10-03, after Empryo's card): a
// rounded `faint` frame on the trunk column, sized to the hunks, one number column (the new
// number on a kept or added line, the old on a removed one) in `faint`,
// `+` in `ok` on an `addBg` row, `-` in `err` on a `delBg` row, the code
// painted by glass's highlighter, an ellipsis row between hunks.
export function renderDiff(t: Table, p: Palette, hunks: ReadonlyArray<Hunk>, o: DiffOptions): RenderElement {
  const lang = langOf(o.path)
  const last = Math.max(1, ...hunks.flatMap(h => [h.oldStart + h.lines.length, h.newStart + h.lines.length]))
  const digits = String(last).length
  type Piece = { text: string; color?: string }
  type Line = { kind: 'add' | 'del' | 'ctx' | 'note'; num: number | null; pieces: Piece[] }
  const lines: Line[] = []
  let widest = 0
  let total = 0
  let hidden = 0
  let add = 0
  let del = 0
  hunks.forEach((h, i) => {
    const state: State = { inBlock: false }
    // one context line before the first change and one after the last;
    // context between changes stays, and the numbers keep counting
    const changed = h.lines.map((l, k) => (l[0] === '+' || l[0] === '-' ? k : -1)).filter(k => k >= 0)
    const lo = changed.length ? changed[0]! - 1 : -Infinity
    const hi = changed.length ? changed[changed.length - 1]! + 1 : Infinity
    let k = -1
    if (i > 0 && total < MAX_DIFF_ROWS) lines.push({ kind: 'note', num: null, pieces: [{ text: G.ellipsis, color: p.faint }] })
    let old = h.oldStart
    let cur = h.newStart
    for (const raw of h.lines) {
      k++
      const head = raw[0]
      const kind = head === '+' ? 'add' : head === '-' ? 'del' : head === '\\' ? 'note' : 'ctx'
      const num = kind === 'del' ? old : cur
      if (kind === 'ctx' || kind === 'del') old++
      if (kind === 'ctx' || kind === 'add') cur++
      if (kind === 'add') add++
      if (kind === 'del') del++
      if (kind === 'ctx' && (k < lo || k > hi)) continue
      total++
      if (total > MAX_DIFF_ROWS) {
        hidden++
        continue
      }
      // tabs expand here: the engine and the terminal disagree on a tab's width
      const body = safeText(raw.slice(1), 2000).replace(/\t/g, '    ')
      widest = Math.max(widest, cellWidth(body))
      if (kind === 'note') {
        lines.push({ kind, num: null, pieces: [{ text: body, color: p.faint }] })
        continue
      }
      const pieces = highlightLine(body, lang, state).map(s => (s.kind === 'plain' ? { text: s.text } : { text: s.text, color: codeColor(p, s.kind) }))
      lines.push({ kind, num, pieces })
    }
  })
  if (hidden > 0) lines.push({ kind: 'note', num: null, pieces: [{ text: G.ellipsis + ` +${plural(hidden, 'line')}`, color: p.faint }] })

  const name = safeText(rel(o.path), 400)
  const counts = (add > 0 ? ` +${add}` : '') + (del > 0 ? ` -${del}` : '')
  const verb = o.verb ? o.verb + ' ' : ''
  const cap = Math.max(20, o.columns - 2 * TREE_INSET)
  const width = Math.min(cap, Math.max(DIFF_MIN, widest + digits + 3 + 4, cellWidth(verb + name + counts) + 8))
  // inside the frame: a border and a padding cell each side
  const inner = width - 4
  const gutter = digits + 3
  const room = Math.max(1, inner - gutter)

  // The frame is drawn by glass, row by row, so the file can sit in the top
  // border, `SPEC.md +1 -1` between the arcs (owner's pick, 2026-10-03; an absolute
  // title over a Box border is clipped by the engine). glass breaks every
  // code line at the room itself, so the engine never wraps inside the card
  // and each row carries its own two edges: no glyph column guesses a height.
  const edge = (s: string) => t.Text({ color: p.faint, children: [s] })
  const out: RenderElement[] = []
  const fixed = 3 + cellWidth(verb + counts) + 3
  const shown = o.path ? clipPath(name, Math.max(4, width - fixed)) : ''
  const titleW = o.path ? cellWidth(verb + shown + counts) + 1 : 0
  out.push(
    t.Text({
      children: [
        edge(G.arcTL + G.rule + (o.path ? ' ' : '')),
        ...(o.path
          ? [
              ...(verb ? [t.Text({ color: p.meta, children: [verb] })] : []),
              t.Text({ color: p.path, children: [shown] }),
              ...(add > 0 ? [' ', t.Text({ color: THEME.success, children: [`+${add}`] })] : []),
              ...(del > 0 ? [' ', t.Text({ color: THEME.error, children: [`-${del}`] })] : []),
              ' ',
            ]
          : []),
        edge(G.rule.repeat(Math.max(1, width - 3 - (o.path ? 1 : 0) - titleW)) + G.arcTR),
      ],
    }),
  )
  for (const l of lines) {
    // 0.5.0: the tints are the active theme's diff slots, so the card
    // matches the engine's own diff panels; 0.5.3: the marks take the
    // theme's success and error (the diff*Word slots are the engine's
    // word-level backgrounds, not text colors). A glass theme sets these to
    // the palette's addBg, delBg, ok and err.
    const bg = l.kind === 'add' ? THEME.diffAdded : l.kind === 'del' ? THEME.diffRemoved : undefined
    const mark = l.kind === 'add' ? '+' : l.kind === 'del' ? '-' : ' '
    const markColor = l.kind === 'add' ? THEME.success : l.kind === 'del' ? THEME.error : p.faint
    chunk(l.pieces, room).forEach((part, n) => {
      const used = part.reduce((w, x) => w + cellWidth(x.text), 0)
      const head: RenderNode[] =
        n === 0 && l.num !== null
          ? [t.Text({ color: bg ? p.meta : p.faint, children: [String(l.num).padStart(digits) + ' '] }), t.Text({ color: markColor, children: [mark + ' '] })]
          : [' '.repeat(gutter)]
      out.push(
        t.Box({
          flexDirection: 'row',
          children: [
            edge(G.pipe + ' '),
            t.Box({
              width: inner,
              flexShrink: 0,
              ...(bg ? { backgroundColor: bg } : {}),
              children: [
                t.Text({
                  wrap: 'truncate-end',
                  children: [...head, ...part.map(x => (x.color ? t.Text({ color: x.color, children: [x.text] }) : x.text)), ' '.repeat(Math.max(0, room - used))],
                }),
              ],
            }),
            edge(' ' + G.pipe),
          ],
        }),
      )
    })
  }
  out.push(edge(G.arcBL + G.rule.repeat(width - 2) + G.arcBR))
  // the card sits on the trunk column: its left edge is the trunk
  return t.Box({ marginLeft: TREE_INSET, marginRight: TREE_INSET, width, flexDirection: 'column', children: out })
}

// colored pieces cut into rows of at most `w` cells, by the engine's ruler
function chunk(pieces: ReadonlyArray<{ text: string; color?: string }>, w: number): { text: string; color?: string }[][] {
  const rows: { text: string; color?: string }[][] = [[]]
  let used = 0
  for (const piece of pieces) {
    let buf = ''
    for (const ch of piece.text) {
      const cw = cellWidth(ch)
      if (used + cw > w && used > 0) {
        if (buf) rows[rows.length - 1]!.push({ ...piece, text: buf })
        rows.push([])
        buf = ''
        used = 0
      }
      buf += ch
      used += cw
    }
    if (buf) rows[rows.length - 1]!.push({ ...piece, text: buf })
  }
  return rows
}

// ---- a Bash result that changed files ------------------------------------

export type ChangedFile = { filePath: string; hunks: Hunk[]; created?: true; deleted?: true }

export type BashResultOptions = {
  /** the painted body shows this many lines before folding the rest */
  maxLines: number
  moreFiles: number
  columns: number
}

// A Bash result whose command rewrote files: the output body as the
// standalone one draws (folded past `maxLines` to a `faint` count), then
// per file, after one trunked row of air, a header `Updated <path> +a -b` and the
// same rounded diff card an Edit gets (owner's request, 2026-10-03: the
// engine's own panel for these was the one pink thing left).
export function renderBashResult(t: Table, p: Palette, lines: string[], files: ReadonlyArray<ChangedFile>, o: BashResultOptions): RenderElement {
  const rows: RenderElement[] = []
  const air = () => trunked(t, p, 1, [t.Text({ children: [''] })])
  if (lines.length > 0) rows.push(renderToolOutput(t, p, lines, { columns: o.columns, maxLines: o.maxLines }))
  for (const f of files) {
    const verb = f.created ? 'Created' : f.deleted ? 'Deleted' : undefined
    rows.push(air())
    // the card's top border names the file; a change with no hunks keeps a header line
    if (f.hunks.length > 0) {
      rows.push(renderDiff(t, p, f.hunks, { path: f.filePath, columns: o.columns, ...(verb ? { verb } : {}) }))
      continue
    }
    rows.push(
      trunked(t, p, 1, [
        t.Text({
          wrap: 'truncate-end',
          children: [
            t.Text({ color: p.meta, children: [(verb ?? 'Updated') + ' '] }),
            t.Text({ color: p.path, children: [safeText(rel(f.filePath), 400)] }),
          ],
        }),
      ]),
    )
  }
  if (o.moreFiles > 0) {
    rows.push(air())
    rows.push(trunked(t, p, 1, [t.Text({ color: p.faint, children: [G.ellipsis + ` +${o.moreFiles} more file${o.moreFiles === 1 ? '' : 's'}`] })]))
  }
  return t.Box({ flexDirection: 'column', children: rows })
}

// ---- folded group --------------------------------------------------------

export type GroupCall = { tool: string; input?: unknown; isRunning: boolean; isErrored: boolean; isInterrupted: boolean }

export type GroupOptions = {
  isActive: boolean
  /** the row's key, which its hover tint needs; null draws it untinted */
  key: string | null
}

// `|- > Read x3  a.ts . b.ts [1 edit]`, all `faint`, the mark in `meta`; a
// failed count in `err`; a live group ends in an ellipsis. No fold button:
// a Button in a transcript row never received its press live (2026-10-03),
// so /expand opens every group. Each MCP server takes a line of its own,
// named once at its head, under one hover (owner's request, 2026-10-07).
export function renderGroupRow(t: Table, p: Palette, calls: ReadonlyArray<GroupCall>, o: GroupOptions): RenderElement {
  const runs = new Map<string, GroupCall[]>()
  for (const c of calls) {
    const server = toolLabel(c.tool).server ?? ''
    const run = runs.get(server)
    if (run) run.push(c)
    else runs.set(server, [c])
  }
  const lines = [...runs].map(([server, run]) => groupLine(t, p, server, run, o.isActive && (runs.size === 1 || run.some(c => c.isRunning))))
  return spaced(t, p, t.Box({
    ...(o.key ? { key: `group:${o.key}`, hover: { backgroundColor: p.rowHover } } : {}),
    flexDirection: 'column',
    children: lines,
  }))
}

function groupLine(t: Table, p: Palette, server: string, calls: GroupCall[], live: boolean): RenderElement {
  const edits = calls.filter(c => isEditTool(c.tool)).length
  const failed = calls.filter(c => c.isErrored || c.isInterrupted).length
  // what the run touched: the tools with counts, then each subject once
  const counts = new Map<string, number>()
  for (const c of calls) {
    const name = toolLabel(c.tool).name
    counts.set(name, (counts.get(name) ?? 0) + 1)
  }
  const tools = [...counts].map(([tool, n]) => (n > 1 ? `${tool} ${G.times}${n}` : tool)).join(sep)
  const subjects = [...new Set(calls.map(c => {
    const a = (c.input ?? {}) as Record<string, unknown>
    const s = str(a, 'file_path') ?? str(a, 'path') ?? str(a, 'pattern') ?? str(a, 'query') ?? str(a, 'url') ?? clip((str(a, 'command') ?? '').replace(/\s+/g, ' '), 60)
    return safeText(rel(s).replace(/\s+/g, ' '), 200)
  }).filter(s => s !== ''))]
  const parts: RenderNode[] = server ? [t.Text({ color: p.faint, children: [server + ' '] })] : []
  parts.push(t.Text({ color: p.tool, children: [tools] }))
  if (subjects.length) parts.push('  ' + subjects.join(sep))
  if (edits > 0) parts.push(sep + plural(edits, 'edit'))
  if (failed > 0) parts.push(sep, t.Text({ color: p.err, children: [`${failed} failed`] }))
  const tail = live ? sep + `${calls.filter(c => c.isRunning).length} running` + G.ellipsis : ''
  return t.Box({
    flexDirection: 'row',
    children: [
      rowHead(t, t.Text({ color: p.faint, children: [G.tee + G.rule + ' '] }), t.Text({ color: p.meta, children: [G.right + ' '] })),
      t.Box({ flexShrink: 1, children: [t.Text({ wrap: 'truncate-end', color: p.faint, children: [...parts, tail] })] }),
    ],
  })
}

// ---- events after the turn -----------------------------------------------

export type EventTask = { status?: string; durationMs?: number }

// a background task's notification as one tree row:
// `|- v Agent "Research Empryo" finished                         1m 12s`
// A Box with a hover style must carry a key, or the validator refuses the
// whole tree and the engine draws its own row. The key is the message's
// own id: two notifications with the same first line must not share one.
// Every event row draws the tee, as tree rows do: knowing the last needs a
// subscription to the session's messages.
export function renderEventRow(t: Table, p: Palette, id: string, text: string, task: EventTask | undefined, expanded = false): RenderElement {
  const linesAll = text.split('\n')
  const at = linesAll.findIndex(l => l.trim() !== '')
  const first = safeText(linesAll[at] ?? '', 400)
  const rest = expanded ? safeText(linesAll.slice(at + 1).join('\n').trim(), MAX_TEXT) : ''
  const status = (task?.status ?? '').toLowerCase()
  const failed = /fail|error|kill|cancel/.test(status)
  // under a tenth of a second the time says nothing, as on a tree row
  const right = typeof task?.durationMs === 'number' && task.durationMs >= 100 ? fmtToolTime(task.durationMs) : ''
  // `Agent "Count hook source lines" finished` draws as a tool row
  const agent = /^Agent "(.+)" \w+/.exec(first)
  const row = spaced(t, p, t.Box({
    key: `event:${id}`,
    flexDirection: 'row',
    hover: { backgroundColor: p.rowHover },
    children: [
      rowHead(t, t.Text({ color: p.faint, children: [G.tee + G.rule + ' '] }), t.Text({ color: failed ? p.err : p.ok, children: [(failed ? G.cross : G.tick) + ' '] })),
      t.Box({ flexGrow: 1, flexShrink: 1, children: [t.Text({ wrap: 'truncate-end', color: p.meta, children: agent ? [t.Text({ color: p.tool, children: ['Agent'] }), '  ' + agent[1]!] : [first] })] }),
      ...(right ? [t.Box({ flexShrink: 0, marginLeft: 2, children: [t.Text({ color: p.faint, children: [right] })] })] : []),
    ],
  }))
  if (rest === '') return row
  // the rest of the notification hangs off the trunk as a Bash body does,
  // one row per line, clipped (a body with no trunk sat off the column)
  const body = rest.split('\n').map(l => t.Text({ wrap: 'truncate-end', color: p.meta, children: [l] }))
  return t.Box({
    flexDirection: 'column',
    children: [row, trunked(t, p, body.length, body)],
  })
}

// a message another agent sent, folded: `|- . Message from @Explore` in
// `private`; no key hint at the right (0.5.3: the hint line and the group
// rows gave theirs up, this was the last)
export function renderMessageRow(t: Table, p: Palette, name: string): RenderElement {
  return spaced(t, p, t.Box({
    key: `message:${name}`,
    flexDirection: 'row',
    hover: { backgroundColor: p.rowHover },
    children: [
      rowHead(t, t.Text({ color: p.faint, children: [G.tee + G.rule + ' '] }), t.Text({ color: p.faint, children: [G.ring + ' '] })),
      t.Box({ flexGrow: 1, flexShrink: 1, children: [t.Text({ wrap: 'truncate-end', color: p.private, children: [`Message from @${safeText(name, 80)}`] })] }),
    ],
  }))
}

// ---- background band -----------------------------------------------------

const BAND_ROWS = 5
const COL_NAME = 20
const COL_MODEL = 22
const COL_STAGE = 14
const COL_TOKENS = 8
// the view and back labels are one width, so a row is the band wide either way
const VIEW_LABEL = 'view'
const BACK_LABEL = 'back'
const VIEW_CELLS = 1 + VIEW_LABEL.length

// `view` on an agent's row, `back` on the one in view: a plain dim Button in
// a keyed Box, as the chevron is (a hover with no keyed Box around it makes
// the engine refuse the tree)
function viewButton(t: Table, p: Palette, agentId: string, inView: boolean, onPress: () => void): RenderElement {
  const key = `band:view:${agentId}`
  return t.Box({ key, children: [t.Button({ key, label: inView ? BACK_LABEL : VIEW_LABEL, plain: true, dimColor: true, hover: { backgroundColor: p.rowHover }, onPress })] })
}

export type BandOptions = {
  agents: GlassAgent[]
  now: number
  columns: number
  open: boolean
  onToggle: Press | null
  /** the slash command that lists tasks, when the session has one */
  tasksCommand: string | null
  /**
   * 0.10.0: opens an agent's transcript in the main view (`$.ui.view`,
   * engine 2.1.300); absent or null, no row draws a button
   */
  onView?: ((agentId: string) => void) | null
  /** the agent whose transcript is in view (`e.props.view.agentId`), if any */
  viewing?: string | null
  /** returns to the main conversation; the row in view draws `back` */
  onBack?: (() => void) | null
}

// the agent's face: eyes level while it thinks, lowered while it reads
function face(a: GlassAgent): string {
  const eye = G.disc
  const mouth = a.stage.startsWith('thinking') ? G.smile : G.down
  return `(${eye}${mouth}${eye})`
}

function shortModel(model: string): string {
  return model.replace(/^claude-/, '').replace(/-\d{8}$/, '')
}

// A rounded frame the band's width, the title in its top edge and the
// oldest agent's elapsed time at the right; one row per live agent, newest
// last, five at most and `+N more`; the bottom edge carries the hint.
// Closed, one strip: the title, the faces, the newest agent's stage.
export function renderBand(t: Table, p: Palette, o: BandOptions): RenderElement {
  const { agents, now } = o
  // the engine draws its `[-]` collapse mark over the band's top-right
  // cells; the frame stops four short of it (2026-10-04)
  const w = Math.max(40, o.columns - 4)
  const oldest = agents.reduce((n, a) => Math.min(n, a.startedAt), now)
  const elapsed = fmtDuration(Math.max(0, now - oldest))
  const titleText = `background${sep}${agents.length}`
  // the chevron's hover tint needs a keyed Box around it: without one the
  // engine refuses the whole tree and draws nothing, so the band was
  // invisible from 0.5.2 to 0.5.3 (found in the debug log, 2026-10-12)
  const chevron = o.onToggle
    ? t.Box({ key: 'band:chevron', children: [t.Button({ key: 'band:toggle', label: o.open ? G.down : G.right, plain: true, dimColor: true, hover: { backgroundColor: p.rowHover }, onPress: o.onToggle })] })
    : t.Text({ color: p.accent, children: [o.open ? G.down : G.right] })
  const title = t.Text({
    children: [
      t.Text({ color: p.accent, children: [G.dotted + ' '] }),
      t.Text({ color: p.accent, bold: true, children: ['background'] }),
      t.Text({ color: p.meta, children: [sep] }),
      t.Text({ color: p.accent, bold: true, children: [String(agents.length)] }),
      ' ',
    ],
  })

  if (!o.open) {
    // `- o background . 3 v - (o_o) (o_o)  Research Empryo . thinking... ----- 1m 25s -`
    // the fill is measured from the strings around it, so the strip is
    // exactly the band wide
    const newest = agents[agents.length - 1]!
    const lead = `${G.rule} `
    const titleStr = `${G.dotted} background${sep}${agents.length} `
    const mid = ` ${G.rule} `
    const tail = ` ${elapsed} ${G.rule}`
    const fixedFor = (faces: string) => cellWidth(lead + titleStr) + 1 + cellWidth(mid + faces) + 2 + 1 + cellWidth(tail)
    // a narrow terminal drops the oldest faces, all of them if it must, so
    // 16 cells stay for the name and the fill; the name then takes what is
    // left but one
    let shown = agents.slice(-BAND_ROWS)
    while (shown.length > 0 && w - fixedFor(shown.map(face).join(' ')) < 16) shown = shown.slice(1)
    const faces = shown.map(face).join(' ')
    const fixed = fixedFor(faces)
    const room = w - fixed
    const name = clip(`${a11(newest.description)}${sep}${newest.stage}`, room >= 16 ? room - 8 : Math.max(0, room - 1))
    const fill = Math.max(1, w - fixed - cellWidth(name))
    return t.Box({
      flexDirection: 'row',
      width: w,
      children: [
        t.Text({ color: p.accent, children: [lead] }),
        title,
        chevron,
        t.Text({ color: p.accent, children: [mid] }),
        t.Text({ color: p.warn, children: [faces] }),
        t.Text({ color: p.meta, children: [`  ${name} `] }),
        t.Text({ color: p.accent, children: [G.rule.repeat(fill)] }),
        t.Text({ color: p.meta, children: [` ${elapsed} `] }),
        t.Text({ color: p.accent, children: [G.rule] }),
      ],
    })
  }

  // the top edge: arc, rule, the title, rules to the elapsed time, arc
  const topUsed = cellWidth(`${G.arcTL}${G.rule} ${G.dotted} background${sep}${agents.length} `) + 1 + 1 + cellWidth(` ${elapsed} ${G.rule}${G.arcTR}`)
  const top = t.Box({
    flexDirection: 'row',
    children: [
      t.Text({ color: p.accent, children: [G.arcTL + G.rule + ' '] }),
      title,
      chevron,
      t.Text({ color: p.accent, children: [' ' + G.rule.repeat(Math.max(1, w - topUsed))] }),
      t.Text({ color: p.meta, children: [` ${elapsed} `] }),
      t.Text({ color: p.accent, children: [G.rule + G.arcTR] }),
    ],
  })
  // the frame and the model column stay accent: a faint frame was tried
  // and the owner wanted the color back (2026-10-11)
  const edge = (s: string) => t.Text({ color: p.accent, children: [s] })
  const inner = w - 4
  const shown = agents.slice(-BAND_ROWS)
  const more = agents.length - shown.length
  const cols = bandColumns(inner, o.onView ? VIEW_CELLS : 0)
  const rows = shown.map(a => {
    const modelText = `${shortModel(a.model)}${a.effort ? sep + a.effort : ''}`
    const inView = o.viewing === a.agentId
    const onView = o.onView
    const press = inView ? () => o.onBack?.() : () => onView?.(a.agentId)
    return t.Box({
      flexDirection: 'row',
      children: [
        edge(G.pipe + ' '),
        t.Text({
          children: [
            t.Text({ color: p.warn, children: [G.diamond + ' ' + face(a) + ' '] }),
            t.Text({ color: inView ? p.accent : p.bold, bold: true, children: [fit(a11(a.description), cols.name)] }),
            ' ',
            t.Text({ color: p.accent, children: [fit(modelText, cols.model)] }),
            ' ',
            t.Text({ color: p.meta, children: [fit(a.stage, cols.stage)] }),
            ' ',
            t.Text({ color: p.meta, children: [fit(a.tokens > 0 ? fmtTokens(a.tokens) : '', cols.tokens)] }),
            ' ',
            t.Text({ color: p.faint, children: [fitPath(rel(a.file), cols.file)] }),
          ],
        }),
        ...(onView ? [t.Text({ children: [' '] }), viewButton(t, p, a.agentId, inView, press)] : []),
        edge(' ' + G.pipe),
      ],
    })
  })
  if (more > 0) {
    rows.push(
      t.Box({
        flexDirection: 'row',
        children: [edge(G.pipe + ' '), t.Text({ color: p.faint, children: [fit(`  +${more} more`, inner)] }), edge(' ' + G.pipe)],
      }),
    )
  }
  const hint = 'They outlive this turn'
  const cmd = o.tasksCommand ? `/${o.tasksCommand}` : ''
  const bottomUsed = 2 + 1 + cellWidth(hint) + 1 + (cmd ? cellWidth(cmd) + 2 : 0) + 2
  const bottom = t.Box({
    flexDirection: 'row',
    children: [
      t.Text({ color: p.accent, children: [G.arcBL + G.rule + ' '] }),
      t.Text({ color: p.faint, children: [hint + ' '] }),
      t.Text({ color: p.accent, children: [G.rule.repeat(Math.max(1, w - bottomUsed))] }),
      ...(cmd ? [t.Text({ color: p.meta, children: [` ${cmd} `] })] : []),
      t.Text({ color: p.accent, children: [G.rule + G.arcBR] }),
    ],
  })
  return t.Box({ flexDirection: 'column', width: w, children: [top, ...rows, bottom] })
}

// A band row's column widths inside `inner` cells: the diamond, a space,
// the five-cell face and a space (8), then name, model, stage, tokens and
// file with one space after each of the first four. The file takes what is
// left; on a narrow terminal the model gives up cells first, then the
// name, the tokens column, the stage, and the name and model again, so a
// row never outgrows its frame.
function bandColumns(inner: number, extra = 0): { name: number; model: number; stage: number; tokens: number; file: number } {
  const c = { name: COL_NAME, model: COL_MODEL, stage: COL_STAGE, tokens: COL_TOKENS }
  let over = 8 + 4 + extra + c.name + c.model + c.stage + c.tokens - inner
  const give = (k: keyof typeof c, min: number) => {
    const d = Math.max(0, Math.min(over, c[k] - min))
    c[k] -= d
    over -= d
  }
  give('model', 8)
  give('name', 8)
  give('tokens', 0)
  give('stage', 6)
  give('model', 1)
  give('name', 1)
  return { ...c, file: Math.max(0, -over) }
}

// a description as one printable line
function a11(s: string): string {
  return safeText(s.replace(/\s+/g, ' ').trim(), 120)
}

// A backgrounded Agent's result, in place of the engine's body (its corner
// bracket broke the trunk, 2026-10-04): one trunked line in `faint`.
export function renderAgentLaunch(t: Table, p: Palette, remote: boolean): RenderElement {
  const text = remote ? `running remotely${sep}/tasks` : `running in the background${sep}${G.arrowDown} to manage`
  return trunked(t, p, 1, [t.Text({ color: p.faint, wrap: 'truncate-end', children: [text] })])
}

// A Bash command that printed nothing, in place of the engine's body (its
// corner bracket broke the trunk, 2026-10-06): one trunked line in `faint`.
export function renderNoOutput(t: Table, p: Palette): RenderElement {
  return trunked(t, p, 1, [t.Text({ color: p.faint, wrap: 'truncate-end', children: ['(No output)'] })])
}

// A loaded skill, in place of the engine's body (its corner bracket sat off
// the trunk, 2026-10-09): one trunked line in `faint`, with the engine's
// tool count and model where it gives them. A forked skill draws as an
// Agent's launch.
export function renderSkillLoad(t: Table, p: Palette, output: unknown): RenderElement {
  const o = (output && typeof output === 'object' ? output : {}) as { status?: unknown; background?: unknown; allowedTools?: unknown; model?: unknown }
  if (o.status === 'forked') return o.background === true ? renderAgentLaunch(t, p, false) : trunked(t, p, 1, [t.Text({ color: p.faint, children: ['done'] })])
  const parts = ['skill loaded']
  if (Array.isArray(o.allowedTools) && o.allowedTools.length > 0) parts.push(`${plural(o.allowedTools.length, 'tool')} allowed`)
  if (typeof o.model === 'string' && o.model !== '') parts.push(safeText(o.model, 80))
  return trunked(t, p, 1, [t.Text({ color: p.faint, wrap: 'truncate-end', children: [parts.join(sep)] })])
}

// A failed non-Bash call's error, in place of the engine's body (its corner
// bracket broke the trunk, 2026-10-06): the reason's first line in `err`,
// the rest a `faint` count; ctrl+o has it whole.
export function renderToolError(t: Table, p: Palette, text: string): RenderElement {
  const lines = text.split('\n').map(l => l.trim()).filter(l => l !== '')
  const rows = [trunked(t, p, 1, [t.Text({ color: p.err, wrap: 'truncate-end', children: [safeText(lines[0] ?? 'Error', 400)] })])]
  if (lines.length > 1) rows.push(trunked(t, p, 1, [t.Text({ color: p.faint, children: [G.ellipsis + ` +${plural(lines.length - 1, 'line')}`] })]))
  return t.Box({ flexDirection: 'column', children: rows })
}

// ---- live clock ----------------------------------------------------------

/** the hover group a call's dot and its tree row share */
export function callScope(id: string): string {
  return ('glass:' + id).slice(0, 64)
}

/** cells the running row's clock takes: `12m 04s` at most */
export const CLOCK_CELLS = 7
// 99h 59m 59s, the longest time seven cells hold
const CLOCK_MAX_MS = ((99 * 60 + 59) * 60 + 59) * 1000

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
function base64(bytes: Uint8Array): string {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const a = bytes[i]!
    const b = i + 1 < bytes.length ? bytes[i + 1]! : 0
    const c = i + 2 < bytes.length ? bytes[i + 2]! : 0
    const n = (a << 16) | (b << 8) | c
    out += B64[(n >> 18) & 63]! + B64[(n >> 12) & 63]!
    out += i + 1 < bytes.length ? B64[(n >> 6) & 63]! : '='
    out += i + 2 < bytes.length ? B64[n & 63]! : '='
  }
  return out
}

// A Raster's cells for the elapsed time, right-aligned in CLOCK_CELLS: each
// cell a [codePoint, fg, bg] triplet of little-endian u32, the background
// the terminal's own (bit 24 alone). ASCII digits and letters only.
export function clockCells(ms: number, fg: string): string {
  // past 99h 59m the clock holds there: `100h 00m` is a cell too wide
  const text = fmtDuration(Math.min(Math.max(0, ms), CLOCK_MAX_MS)).padStart(CLOCK_CELLS)
  const color = /^#[0-9a-f]{6}$/i.test(fg) ? parseInt(fg.slice(1), 16) : 0x01000000
  const words = new Uint32Array(CLOCK_CELLS * 3)
  for (let i = 0; i < CLOCK_CELLS; i++) {
    words[i * 3] = text.charCodeAt(i)
    words[i * 3 + 1] = color
    words[i * 3 + 2] = 0x01000000
  }
  return base64(new Uint8Array(words.buffer))
}

// ---- the hint line under the prompt ----------------------------------------

// The engine's hint, its key reminders dropped (owner's request, 2026-10-04:
// keep the line under the prompt clean): `(shift+tab to cycle)` and
// `<left arrow> for agents` go. The vim mode comes first, wherever the engine
// put it (live: `<mode> . -- INSERT --`), then the permission mode. Null when
// the hint has neither and nothing was dropped (`? for shortcuts`), so the
// engine keeps its own line.
export function cleanHint(hint: string): { vim: string; rest: string } | null {
  const dropped = hint
    .replace(/\s*\((?:shift|ctrl|alt|meta)\+[a-z]+ to cycle\)/gi, '')
    .replace(new RegExp('\\s*' + G.middot + '?\\s*' + G.arrowLeft + '\\s*for agents', 'g'), '')
  const vimMatch = /--\s*[A-Z]+\s*--/.exec(dropped)
  const vim = vimMatch ? vimMatch[0] : ''
  const sepRe = new RegExp('^[\\s' + G.middot + ']+|[\\s' + G.middot + ']+$', 'g')
  const rest = (vim ? dropped.replace(vim, ' ') : dropped).replace(new RegExp('\\s*' + G.middot + '\\s*' + G.middot + '\\s*', 'g'), ' ' + G.middot + ' ').replace(sepRe, '')
  const changed = dropped !== hint
  if (!changed && !vim && !MODE_RE.test(rest)) return null
  return { vim, rest }
}

const MODE_RE = /mode on|accept edits on|plan mode/i

// the vim mode in `accentUser` (the person's own color: typing is theirs),
// the permission mode in the active theme's own slot for it (0.5.0: the
// engine's panels and glass agree under any theme): plan `planMode`,
// accepting edits `autoAccept`, auto and bypass `warning`; anything else `meta`
export function renderHint(t: Table, p: Palette, h: { vim: string; rest: string }): RenderElement {
  const modeColor = /auto|bypass/i.test(h.rest) ? THEME.warning : /plan/i.test(h.rest) ? THEME.planMode : /accept/i.test(h.rest) ? THEME.autoAccept : p.meta
  return t.Text({
    wrap: 'truncate-end',
    children: [
      ...(h.vim ? [t.Text({ color: /INSERT/.test(h.vim) ? p.accentUser : p.meta, children: [h.vim] })] : []),
      ...(h.vim && h.rest ? ['  '] : []),
      ...(h.rest ? [t.Text({ color: modeColor, children: [h.rest] })] : []),
    ],
  })
}

files.hooks/glyphs.ts:
// Every non-ASCII glyph the mod draws, built from code points. The agent
// tool path has dropped private-use literals on the way into a file before
// (the pill caps once shipped as ''), so no glyph outside printable ASCII
// is ever written as a literal in hooks/, comments included. Verify with:
//   LC_ALL=C grep -rn '[^ -~]' hooks/   -> must print nothing
const cp = (n: number) => String.fromCodePoint(n)

export const G = {
  /** gutter mark beside a paragraph that needs the reader: LEFT ONE QUARTER BLOCK, U+258E */
  mark: cp(0x258e),
  /** rules and table header line: BOX DRAWINGS LIGHT HORIZONTAL, U+2500 */
  rule: cp(0x2500),
  /** list markers: BULLET U+2022, WHITE BULLET U+25E6, BALLOT BOX U+2610, BALLOT BOX WITH CHECK U+2611 */
  dot: cp(0x2022),
  ring: cp(0x25e6),
  box: cp(0x2610),
  check: cp(0x2611),
  /** separator: MIDDLE DOT, U+00B7 */
  middot: cp(0x00b7),
  /** HORIZONTAL ELLIPSIS, U+2026 */
  ellipsis: cp(0x2026),
  /** tree connectors: BOX DRAWINGS LIGHT VERTICAL AND RIGHT U+251C, VERTICAL U+2502 */
  tee: cp(0x251c),
  pipe: cp(0x2502),
  /** status marks: CHECK MARK U+2713, BALLOT X U+2717, WHITE CIRCLE U+25CB */
  tick: cp(0x2713),
  cross: cp(0x2717),
  hollow: cp(0x25cb),
  /** FISHEYE U+25C9: the assistant header mark and a folded group */
  fisheye: cp(0x25c9),
  /** BLACK DIAMOND U+25C6: the user row and a band row */
  diamond: cp(0x25c6),
  /** DOTTED CIRCLE U+25CC: the band header */
  dotted: cp(0x25cc),
  /** BLACK RIGHT-POINTING SMALL TRIANGLE U+25B8, DOWN U+25BE: fold chevrons */
  right: cp(0x25b8),
  down: cp(0x25be),
  /** the band's rounded frame: BOX DRAWINGS LIGHT ARC DOWN AND RIGHT U+256D, DOWN AND LEFT U+256E, UP AND RIGHT U+2570, UP AND LEFT U+256F */
  arcTL: cp(0x256d),
  arcTR: cp(0x256e),
  arcBL: cp(0x2570),
  arcBR: cp(0x256f),
  /** the count sign in `Bash x3`: MULTIPLICATION SIGN U+00D7 */
  times: cp(0xd7),
  /** a status dot: BLACK CIRCLE U+25CF */
  disc: cp(0x25cf),
  /** the agent face's smile: UNDERTIE U+203F */
  smile: cp(0x203f),
  /** TWO JOINED SQUARES U+29C9: the dots line's Copy button (0.5.0) */
  copy: cp(0x29c9),
  /** DOWNWARDS ARROW U+2193: the engine's `down to manage` key */
  arrowDown: cp(0x2193),
  /** LEFTWARDS ARROW U+2190: the engine's `left for agents` key */
  arrowLeft: cp(0x2190),
